236	// ════════════════════════════════════════════════════════════════════════
237	//  Canonical Major-K smem stager. The ss-wgmma operand smem tile (MN rows x
238	//  K=16 bf16) MUST be in the CUTLASS Major-K INTERLEAVE layout (wgmma.cuh):
239	//      idx(mn,k) = (k/8)*(MN*8) + mn*8 + (k%8)
240	//  This helper writes ONE such MN x 16 tile, pulling element (mn, k) from a
241	//  caller-provided accessor `src(mn, kbase + k)`. Routing the source axis
242	//  through the accessor is what lets the SAME wgmma issue (TransA=0/TransB=0,
243	//  the substrate-validated orientation) serve fwd / dX / dW: the staging loop
244	//  transposes physically; the engine never leaves the gated path.
245	//
246	//  Cooperative over `nthreads` threads starting at thread `t0` (a warpgroup).
247	// ════════════════════════════════════════════════════════════════════════
248	template <int MN, typename Src>
249	__device__ __forceinline__ void stage_kmajor_tile(
250	        __nv_bfloat16* smem_tile, int kbase, Src src, int t0, int nthreads) {
251	    // MN*16 elements, each thread strides.
252	    #pragma unroll 1
253	    for (int i = t0; i < MN * wgs::kWgmmaAtomK; i += nthreads) {
254	        const int mn = i / wgs::kWgmmaAtomK;

709	//  (in_proj/out_proj/ff0/ff2) run on wgmma (M=nrows, N-tiled); attention/LN/
710	//  GELU are scalar fp32 over the tile; head/CE are scalar per-sample (M=nsamp<
711	//  64). Writes the DecActs X-inputs (bf16 dW operands), the per-CTA tile scratch
712	//  (qkv/ff0pre/attn/LN caches/x1/finalin/logits the bwd needs), and returns the
713	//  tile's summed NLL (thread 0 holds it). `tok_ids`/`tgt_ids` are HBM int32.
714	//
715	//  DATAFLOW (DecActs X-regions = bf16 dW operands AND inter-stage operands;
716	//  dedicated fp32 scratch for residuals/LN; weights convert fp32→bf16 on read):
717	//    X_in[li]  := layer input (bf16)           [embedding for li=0]
718	//    qkv(bf16) := X_in @ in_w^T + in_b   (in_b folded fp32 → re-round bf16)
719	//    ctx       := attn(qkv) → X_ctx[li] (bf16, out_proj input + dW operand)
720	//    a(work)   := X_ctx @ out_w^T ; r1=X_in+a+out_b (work); n1(r1)→x1(fp32)→X_x1[li]
721	//    ff0(work) := X_x1 @ ff0_w^T ; (ff0+ff0_b)→ff0pre(bf16); gelu(ff0+ff0_b)→X_gact[li](bf16)
722	//    ff2(work) := X_gact @ ff2_w^T ; r2=x1+ff2+ff2_b (work); n2(r2)→X_in[li+1]
723	//                 (last layer: n2→finalin fp32, the head input)
724	//  BIASES (in/out/ff0/ff2) are folded in fp32 at these points (the oracle adds
725	//  them in fp32 after the bf16 matmul); LN β + head out_b were already applied.
726	// ════════════════════════════════════════════════════════════════════════
727	__device__ float dectc_forward_tile(
728	        const DecWeights& w, int g0, int nrows, const DecActs& acts,
729	        const DecTileScratch& sc, const int* __restrict__ tok_ids,
730	        const int* __restrict__ tgt_ids,
731	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red) {
732	    const int nsamp = nrows / dec::kSeq;
733	    // ── Embedding: X_in[0][r] = tok[token_id[g0+r]] + pos[(g0+r)%S]. bf16. ──
734	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
735	        const int r = idx / dec::kD, j = idx % dec::kD;
736	        const int g = g0 + r;
737	        const int tid = tok_ids[g];
738	        const int sp = g % dec::kSeq;            // position within the sample
739	        float v = w.tok[(int64_t)tid * dec::kD + j] + w.pos[(int64_t)sp * dec::kD + j];
740	        acts.X_in[0][(int64_t)g * dec::kD + j] = __float2bfloat16(v);
741	    }
742	    __syncthreads();
743	
744	    for (int li = 0; li < dec::kLayers; ++li) {
745	        const DecWeights::Layer& L = w.layer[li];
746	        const __nv_bfloat16* Xin = acts.X_in[li] + (int64_t)g0 * dec::kD;        // [nrows,d]
747	        // qkv = Xin @ in_w^T + in_b   (N=3d, K=d). bf16 → scratch.qkv[li].
748	        dectc_gemm_fwd<SG_TUNED_TILE_N>(Xin, L.in_w, sc.qkv[li], dec::kD, 3 * dec::kD, sA, sB);
749	        __syncthreads();
750	        // add in_b (the fwd GEMM did W only; bias folded in scalar here for qkv —
751	        // matches the bf16-faithful oracle qkv = bf(x_in @ bf(in_w)^T + in_b)).
752	        for (int idx = threadIdx.x; idx < nrows * 3 * dec::kD; idx += blockDim.x) {
753	            const int j = idx % (3 * dec::kD);
754	            float v = __bfloat162float(sc.qkv[li][idx]) + L.in_b[j];
755	            sc.qkv[li][idx] = __float2bfloat16(v);
756	        }
757	        __syncthreads();
758	        // attention → ctx (work fp32) + attn[li] weights.
759	        dectc_attn_fwd_tile(sc.qkv[li], nrows, sc.work, sc.attn[li]);
760	        // ctx bf16 → X_ctx[li] (out_proj input + its dW operand).
761	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
762	            const int r = idx / dec::kD, j = idx % dec::kD;
763	            acts.X_ctx[li][(int64_t)(g0 + r) * dec::kD + j] = __float2bfloat16(sc.work[(int64_t)r * dec::kD + j]);
764	        }
765	        __syncthreads();
766	        // a = X_ctx @ out_w^T (+ out_b)  (N=d, K=d). fp32 → work.
767	        dectc_gemm_fwd_f32<SG_TUNED_TILE_N>(acts.X_ctx[li] + (int64_t)g0 * dec::kD, L.out_w,
768	                                            sc.work, dec::kD, dec::kD, sA, sB);
769	        __syncthreads();
770	        // r1 = Xin + a + out_b → work (fp32). out_b folded here (the GEMM did W only)
771	        // — matches the oracle a = ctx_b @ out_w^T + out_b kept fp32 through r1.
772	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
773	            const int r = idx / dec::kD, j = idx % dec::kD;
774	            sc.work[(int64_t)r * dec::kD + j] += __bfloat162float(Xin[(int64_t)r * dec::kD + j]) + L.out_b[j];
775	        }
776	        __syncthreads();
777	        // n1(r1) → x1 (fp32) + caches[li]; then bf16 → X_x1[li] (ff0 input + dW operand).
778	        dectc_ln_fwd_tile(sc.work, L.n1_w, L.n1_b, nrows, sc.x1, sc.n1x[li], sc.n1i[li], red);

806	        }
807	        __syncthreads();
808	        if (li + 1 < dec::kLayers) {
809	            // n2(r2) → finalin (fp32 reused) + n2 caches[li]; bf16 → X_in[li+1].
810	            dectc_ln_fwd_tile(sc.work, L.n2_w, L.n2_b, nrows, sc.finalin, sc.n2x[li], sc.n2i[li], red);
811	            for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
812	                const int r = idx / dec::kD, j = idx % dec::kD;
813	                acts.X_in[li + 1][(int64_t)(g0 + r) * dec::kD + j] = __float2bfloat16(sc.finalin[(int64_t)r * dec::kD + j]);
814	            }
815	            __syncthreads();
816	        } else {
817	            // last layer: n2(r2) → finalin (fp32, all positions; head reads last pos) + n2 caches[li].
818	            dectc_ln_fwd_tile(sc.work, L.n2_w, L.n2_b, nrows, sc.finalin, sc.n2x[li], sc.n2i[li], red);
819	        }
820	    }
821	
822	    // ── Final norm + head + CE, scalar PER-SAMPLE on the LAST position only.
823	    //    finalin holds the last-layer n2 output [nrows,d] fp32. ──
824	    float nll_acc = 0.0f;
825	    for (int si = 0; si < nsamp; ++si) {
826	        const int rlast = si * dec::kSeq + (dec::kSeq - 1);
827	        const float* hlast = sc.finalin + (int64_t)rlast * dec::kD;
828	        float sum = 0.0f;
829	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) sum += hlast[j];
830	        float mean = dec_block_sum(sum, red) / (float)dec::kD;
831	        float vs = 0.0f;
832	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) { float c = hlast[j] - mean; vs += c * c; }
833	        float var = dec_block_sum(vs, red) / (float)dec::kD;
834	        float iv = rsqrtf(var + dec::kLnEps);
835	        if (threadIdx.x == 0) sc.fni[rlast] = iv;
836	        // fn_xhat cache (last row); hn → X_hn (bf16 head dW operand) AND reuse the
837	        // X_hn bf16 as the scalar head input (read back below).
838	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
839	            float xh = (hlast[j] - mean) * iv;
840	            sc.fnx[(int64_t)rlast * dec::kD + j] = xh;
841	            float hn = xh * w.norm_w[j] + w.norm_b[j];
842	            acts.X_hn[(int64_t)si_global(g0, si) * dec::kD + j] = __float2bfloat16(hn);
843	        }
844	        __syncthreads();
845	        // logits[o] = hn · out_w[o] + out_b[o]  (scalar; hn read from X_hn bf16 so the
846	        // head input == the head dW operand exactly). Store into sc.logits[si*V..].
847	        float* lg = sc.logits + (int64_t)si * dec::kVocab;
848	        const __nv_bfloat16* hnb = acts.X_hn + (int64_t)si_global(g0, si) * dec::kD;
849	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
850	            const float* Wr = w.out_w + (int64_t)o * dec::kD;
851	            float acc = w.out_b[o];
852	            #pragma unroll 4
853	            for (int k = 0; k < dec::kD; ++k) acc += __bfloat162float(hnb[k]) * Wr[k];
854	            lg[o] = acc;
855	        }
856	        __syncthreads();
857	        int tgt = tgt_ids[si_global(g0, si)];
858	        float lmax = -CUDART_INF_F;
859	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) lmax = fmaxf(lmax, lg[o]);
860	        lmax = dec_block_max(lmax, red);
861	        float es = 0.0f;
862	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) es += __expf(lg[o] - lmax);
863	        es = dec_block_sum(es, red);
864	        float logz = lmax + __logf(es);
865	        if (threadIdx.x == 0) nll_acc += (logz - lg[tgt]);
866	        __syncthreads();
867	    }
868	    return nll_acc;
869	}
