871	// Attention BACKWARD over a tile (the oracle's 3-pass form, tile-batched).
872	// Reads qkv (bf16), attn weights, and dctx [nrows,d] fp32; writes dqkv [nrows,3d]
873	// fp32 into `dqkv_out`. dsc is the per-CTA dscores scratch. Mirror of
874	// dec_backward_sample's attention block (A: dv, B: dscores, C: dq/dk), looped
875	// over the tile's samples. scale = 1/sqrt(dh).
876	__device__ __forceinline__ void dectc_attn_bwd_tile(
877	        const __nv_bfloat16* __restrict__ qkv, const float* __restrict__ attn_w,
878	        const float* __restrict__ dctx, int nrows,
879	        float* __restrict__ dqkv_out, float* __restrict__ dsc) {
880	    const int nsamp = nrows / dec::kSeq;
881	    const float scale = dec::attn_scale();
882	    // A: dv[kj] = Σ_{qi>=kj} attn[qi,kj] * dctx[qi].  Owner: (sample,kj,head,t).
883	    for (int r = threadIdx.x; r < nsamp * dec::kSeq * dec::kHeads * dec::kDhead; r += blockDim.x) {
884	        const int si  = r / (dec::kSeq * dec::kHeads * dec::kDhead);
885	        int rem = r % (dec::kSeq * dec::kHeads * dec::kDhead);
886	        const int kj  = rem / (dec::kHeads * dec::kDhead);
887	        rem = rem % (dec::kHeads * dec::kDhead);
888	        const int hh  = rem / dec::kDhead, t = rem % dec::kDhead;
889	        const int qoff = hh * dec::kDhead;
890	        const int rbase = si * dec::kSeq;
891	        const float* aw = attn_w + ((int64_t)(si * dec::kHeads + hh) * dec::kSeq) * dec::kSeq;  // [S,S]
892	        float acc = 0.0f;
893	        #pragma unroll
894	        for (int qi = kj; qi < dec::kSeq; ++qi)
895	            acc += aw[qi * dec::kSeq + kj] * dctx[(int64_t)(rbase + qi) * dec::kD + qoff + t];
896	        dqkv_out[(int64_t)(rbase + kj) * 3 * dec::kD + 2 * dec::kD + qoff + t] = acc;   // dv block
897	    }
898	    __syncthreads();
899	    // B: dscores ds[qi,kj] = attn*(datt - Σ_k datt*attn)*scale, masked kj>qi → 0.
900	    //    datt[kj] = Σ_t dctx[qi,qoff+t]*v[kj,qoff+t]. Owner: (sample,head,qi).
901	    for (int r = threadIdx.x; r < nsamp * dec::kHeads * dec::kSeq; r += blockDim.x) {
902	        const int si = r / (dec::kHeads * dec::kSeq);
903	        int rem = r % (dec::kHeads * dec::kSeq);
904	        const int hh = rem / dec::kSeq, qi = rem % dec::kSeq;
905	        const int qoff = hh * dec::kDhead;
906	        const int rbase = si * dec::kSeq;
907	        const float* aw = attn_w + ((int64_t)(si * dec::kHeads + hh) * dec::kSeq) * dec::kSeq;
908	        float datt[dec::kSeq];
909	        #pragma unroll
910	        for (int kj = 0; kj < dec::kSeq; ++kj) {
911	            if (kj > qi) { datt[kj] = 0.0f; continue; }
912	            float acc = 0.0f;
913	            #pragma unroll
914	            for (int t = 0; t < dec::kDhead; ++t)
915	                acc += dctx[(int64_t)(rbase + qi) * dec::kD + qoff + t]
916	                     * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * dec::kD + 2 * dec::kD + qoff + t]);
917	            datt[kj] = acc;
918	        }
919	        float dot = 0.0f;
920	        #pragma unroll
921	        for (int kj = 0; kj <= qi; ++kj) dot += datt[kj] * aw[qi * dec::kSeq + kj];
922	        float* ds = dsc + ((int64_t)(si * dec::kHeads + hh) * dec::kSeq + qi) * dec::kSeq;
923	        #pragma unroll
924	        for (int kj = 0; kj < dec::kSeq; ++kj) {
925	            float a = aw[qi * dec::kSeq + kj];
926	            ds[kj] = (kj <= qi) ? a * (datt[kj] - dot) * scale : 0.0f;
927	        }
928	    }
929	    __syncthreads();
930	    // C: dq[qi] = Σ_kj ds[qi,kj]*k[kj]; dk[kj] = Σ_qi ds[qi,kj]*q[qi]. Owner: (sample,pos,head,t).
931	    for (int r = threadIdx.x; r < nsamp * dec::kSeq * dec::kHeads * dec::kDhead; r += blockDim.x) {
932	        const int si = r / (dec::kSeq * dec::kHeads * dec::kDhead);
933	        int rem = r % (dec::kSeq * dec::kHeads * dec::kDhead);
934	        const int pos = rem / (dec::kHeads * dec::kDhead);
935	        rem = rem % (dec::kHeads * dec::kDhead);
936	        const int hh = rem / dec::kDhead, t = rem % dec::kDhead;
937	        const int qoff = hh * dec::kDhead;
938	        const int rbase = si * dec::kSeq;
939	        const float* ds = dsc + ((int64_t)(si * dec::kHeads + hh) * dec::kSeq) * dec::kSeq;  // [S,S]
940	        float dq = 0.0f, dk = 0.0f;
941	        #pragma unroll
942	        for (int kj = 0; kj < dec::kSeq; ++kj) {
943	            dq += ds[pos * dec::kSeq + kj] * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * dec::kD + dec::kD + qoff + t]);
944	            dk += ds[kj * dec::kSeq + pos] * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * dec::kD + qoff + t]);
945	        }
946	        dqkv_out[(int64_t)(rbase + pos) * 3 * dec::kD + qoff + t] = dq;             // dq block
947	        dqkv_out[(int64_t)(rbase + pos) * 3 * dec::kD + dec::kD + qoff + t] = dk;   // dk block
948	    }
949	    __syncthreads();
950	}
