952	// ════════════════════════════════════════════════════════════════════════
953	//  BACKWARD over one TOKEN TILE. Assumes dectc_forward_tile ran for THIS tile
954	//  (scratch + DecActs X-inputs populated). Fork B: computes dX via wgmma and
955	//  WRITES the dY output-adjoints to DecActs (dY_qkv/dY_a/dY_ff0/dY_ff2/
956	//  dY_logits) + dh0 for P2's output-stationary dW — it does NOT touch the
957	//  weight dW here. ACCUMULATES the 10 LN-vector grads (γ/β) into the per-CTA
958	//  LN-vec partials `lnvec` [kNumLnVec × d] (deterministic single-owner-per-j).
959	//  `B` is the full batch (CE mean scale). Mirrors dec_backward_sample.
960	//
961	//  dqkv/dctx/dgact intermediates use the fp32 `work` buffer + a second fp32
962	//  buffer `work2` (caller passes both, each [nrows×dff]); dh (running adjoint)
963	//  is the dedicated scratch.dh.
964	// ════════════════════════════════════════════════════════════════════════
965	__device__ void dectc_backward_tile(

965	__device__ void dectc_backward_tile(
966	        const DecWeights& w, int g0, int nrows, int B, const DecActs& acts,
967	        const DecTileScratch& sc, const int* __restrict__ tgt_ids,
968	        float* __restrict__ lnvec, float* __restrict__ work2,
969	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red) {
970	    const int nsamp = nrows / dec::kSeq;
971	    // LN-vec partial slots (dense order; see kLnVecTensorIdx).
972	    float* gn_n1w[dec::kLayers]; float* gn_n1b[dec::kLayers];
973	    float* gn_n2w[dec::kLayers]; float* gn_n2b[dec::kLayers];
974	    for (int li = 0; li < dec::kLayers; ++li) {
975	        gn_n1w[li] = lnvec + (int64_t)(li * 4 + 0) * dec::kD;
976	        gn_n1b[li] = lnvec + (int64_t)(li * 4 + 1) * dec::kD;
977	        gn_n2w[li] = lnvec + (int64_t)(li * 4 + 2) * dec::kD;
978	        gn_n2b[li] = lnvec + (int64_t)(li * 4 + 3) * dec::kD;
979	    }
980	    float* gn_normw = lnvec + (int64_t)8 * dec::kD;
981	    float* gn_normb = lnvec + (int64_t)9 * dec::kD;
982	
983	    // ── CE bwd (per sample): dlogits = (softmax - onehot)/B, overwrite logits.
984	    //    head bwd: dY_logits[si] = dlogits (the head dW operand); dhn = dlogits@out_w.
985	    //    final-norm bwd: dh_last (last position only) → scratch.dh (zero others). ──
986	    // First zero scratch.dh for the whole tile (only last positions get grad).
987	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) sc.dh[idx] = 0.0f;
988	    __syncthreads();
989	    for (int si = 0; si < nsamp; ++si) {
990	        const int rlast = si * dec::kSeq + (dec::kSeq - 1);
991	        const int gs = si_global(g0, si);
992	        float* lg = sc.logits + (int64_t)si * dec::kVocab;
993	        int tgt = tgt_ids[gs];
994	        // softmax of cached logits.
995	        float lmax = -CUDART_INF_F;
996	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) lmax = fmaxf(lmax, lg[o]);
997	        lmax = dec_block_max(lmax, red);
998	        float es = 0.0f;
999	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) es += __expf(lg[o] - lmax);
1000	        es = dec_block_sum(es, red);
1001	        float inv_es = 1.0f / es;
1002	        // dlogits → overwrite lg, AND write to dY_logits[gs] (bf16, head dW operand).
1003	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
1004	            float smo = __expf(lg[o] - lmax) * inv_es;
1005	            float dl = (smo - ((o == tgt) ? 1.0f : 0.0f)) / (float)B;
1006	            lg[o] = dl;
1007	            acts.dY_logits[(int64_t)gs * dec::kVocab + o] = __float2bfloat16(dl);
1008	        }
1009	        __syncthreads();
1010	        // dhn[j] = Σ_o dlogits[o] * out_w[o,j]  (head dX), feature-parallel → dh row rlast.
1011	        // Then final-norm bwd of that single row → scratch.dh[rlast].
1012	        // Use fnx cache (xhat) + fni (inv). Accumulate norm γ/β. (head dW is P2.)
1013	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1014	            float dhn = 0.0f;
1015	            for (int o = 0; o < dec::kVocab; ++o)
1016	                dhn += lg[o] * w.out_w[(int64_t)o * dec::kD + j];
1017	            // final-norm bwd needs the row-reduce of dxhat; stash dhn into work row rlast.
1018	            sc.work[(int64_t)rlast * dec::kD + j] = dhn;
1019	        }
1020	        __syncthreads();
1021	        // norm γ/β: dnorm_w[j] += dhn*xhat; dnorm_b[j] += dhn. (Only last pos contributes.)
1022	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1023	            float dhn = sc.work[(int64_t)rlast * dec::kD + j];
1024	            float xh = sc.fnx[(int64_t)rlast * dec::kD + j];
1025	            gn_normw[j] += dhn * xh; gn_normb[j] += dhn;
1026	        }
1027	        __syncthreads();
1028	        // LN dx (single row): dxhat=dhn*norm_w; reduce; dh[rlast] = inv*(dxhat-(sda+xhat*sdax)/d).
1029	        {
1030	            const float* dyr = sc.work + (int64_t)rlast * dec::kD;
1031	            const float* xhr = sc.fnx + (int64_t)rlast * dec::kD;
1032	            float sda = 0.0f, sdax = 0.0f;
1033	            for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1034	                float dxhat = dyr[j] * w.norm_w[j]; sda += dxhat; sdax += dxhat * xhr[j];
1035	            }
1036	            sda = dec_block_sum(sda, red); sdax = dec_block_sum(sdax, red);
1037	            float iv = sc.fni[rlast];
1038	            for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1039	                float dxhat = dyr[j] * w.norm_w[j];
1040	                sc.dh[(int64_t)rlast * dec::kD + j] = iv * (dxhat - (sda + xhr[j] * sdax) / (float)dec::kD);
1041	            }
1042	            __syncthreads();
1043	        }
1044	    }
1045	    // scratch.dh now = grad wrt last-layer output [nrows,d] (only last positions nonzero).
1046	
1047	    // ── per-layer backward (reverse). dh is the running adjoint (grad wrt the
1048	    //    layer's n2 output). All fwd intermediates are in scratch/DecActs (NO
1049	    //    recompute). ──
1050	    for (int li = dec::kLayers - 1; li >= 0; --li) {
1051	        const DecWeights::Layer& L = w.layer[li];
1052	        // n2 bwd: dh → dr2 (work fp32), accumulate n2 γ/β. xhat=n2x[li], inv=n2i[li].
1053	        dectc_ln_bwd_tile(sc.dh, sc.n2x[li], sc.n2i[li], L.n2_w, nrows, sc.work, gn_n2w[li], gn_n2b[li], red);
1054	        // r2 = x1 + ff2 → dx1 = dr2 (residual), dff2 = dr2. dff2 → dY_ff2 acts (bf16).
1055	        // dx1 starts as dr2 (copy into work2), the FFN path adds to it.
1056	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1057	            work2[idx] = sc.work[idx];   // dx1 := dr2 (residual part)
1058	            acts.dY_ff2[li][(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.work[idx]);  // dff2
1059	        }
1060	        __syncthreads();
1061	        // ff2 dX: dgact = dff2 @ ff2_w  (N=dff, K=d). fp32 → tw? need a [nrows,dff] buffer.
1062	        //   Use sc.work (currently dr2, no longer needed — dx1 saved in work2, dff2 in acts).
1063	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_ff2[li] + (int64_t)g0 * dec::kD, L.ff2_w,
1064	                                           sc.work, dec::kDff, dec::kD, sA, sB);  // dgact [nrows,dff]
1065	        __syncthreads();
1066	        // dff0 = dgact * gelu'(ff0pre) → dY_ff0 acts (bf16) AND keep fp32 in sc.work for dX.
1067	        for (int idx = threadIdx.x; idx < nrows * dec::kDff; idx += blockDim.x) {
1068	            float dff0 = sc.work[idx] * dec_gelu_grad(__bfloat162float(sc.ff0pre[li][idx]));
1069	            sc.work[idx] = dff0;
1070	            acts.dY_ff0[li][(int64_t)g0 * dec::kDff + idx] = __float2bfloat16(dff0);
1071	        }
1072	        __syncthreads();
1073	        // ff0 dX: dx1 += dff0 @ ff0_w  (output width Kin=d, contract Nout=dff). fp32
1074	        //   → sc.x1 (free now — fwd x1 consumed); then add to work2.
1075	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_ff0[li] + (int64_t)g0 * dec::kDff, L.ff0_w,
1076	                                           sc.x1, /*Kin=*/dec::kD, /*Nout=*/dec::kDff, sA, sB);  // dx1_ffn [nrows,d]
1077	        __syncthreads();
1078	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
1079	            work2[idx] += sc.x1[idx];   // dx1 = residual + FFN path
1080	        __syncthreads();
