1393	        const DecDwSpec spec[9], float* __restrict__ grad, int cta, int nCTA) {
1394	    // exclusive prefix of Nout across the 9 specs → total bias-output count.
1395	    int pre[10];
1396	    pre[0] = 0;
1397	    #pragma unroll
1398	    for (int s = 0; s < 9; ++s) pre[s + 1] = pre[s] + spec[s].Nout;
1399	    const int total = pre[9];
1400	    const int stride = nCTA * blockDim.x;
1401	    for (int go = cta * blockDim.x + threadIdx.x; go < total; go += stride) {
1402	        // decode global output index → (spec s, local row o). 9 specs → linear scan.
1403	        int s = 0;
1404	        #pragma unroll
1405	        for (int t = 0; t < 9; ++t) if (go >= pre[t + 1]) s = t + 1;
1406	        const DecDwSpec& sp = spec[s];
1407	        const int o = go - pre[s];
