1457	// BUILD the per-vocab-row token lists (counting sort). Single CTA (caller guards
1458	// cta==0); runs in the P1 window so it overlaps fwd/bwd and the existing B1
1459	// barrier fences it before the P2 consume — NO new barrier. `row_start` is
1460	// [V+1] int32 (CSR offsets), `perm` is [T] int32 (token positions, ascending t
1461	// within each vocab-row bucket). All integer ops → bit-exact + deterministic.
1462	//
1463	// COST: O(T), PARALLEL over kW worker lanes (HBM-latency hidden) so the build is a
1464	// few hundred µs — far below the consume saving it enables. DETERMINISM via a fixed
1465	// STRUCTURAL decomposition: worker w owns the CONTIGUOUS t-chunk [w·C,(w+1)·C); it
1466	// histograms then scatters its chunk in ascending t into a per-(worker,row) slice
1467	// of perm whose base sits AFTER all lower-w workers' slices for the same row. Lower
1468	// w ⇒ lower t, and within a worker ascending t ⇒ each row's perm bucket is GLOBALLY
1469	// ascending t — the SAME order the old single-cursor scatter (and the old owner-scan
1470	// accumulation) produced, so bit-identical. All integer ops; no atomics on the hot
1471	// path. tok_ids is HBM int32 [T]. row_start is [V+1] (CSR offsets); perm is [T].
1472	__device__ __forceinline__ void dectc_embed_build_lists(
1473	        const int* __restrict__ tok_ids, int T,
1474	        int* __restrict__ row_start, int* __restrict__ perm) {
1475	    constexpr int kW = 64;                         // worker lanes (latency hiding)
1476	    __shared__ int wcnt[kW * dec::kVocab];         // per-(worker,row) count, then base cursor
1477	    // floor-balanced contiguous t-chunk per worker w: [c0(w), c0(w+1)).
1478	    auto c0 = [&] (int w) -> int { return (int)(((int64_t)w * T) / kW); };
1479	    // 1) zero the per-worker histograms (all threads).
1480	    for (int i = threadIdx.x; i < kW * dec::kVocab; i += blockDim.x) wcnt[i] = 0;
1481	    __syncthreads();
1482	    // 2) each of the first kW threads histograms its contiguous t-chunk into its own
1483	    //    row of wcnt (no atomics — private per worker).
1484	    if (threadIdx.x < kW) {
1485	        const int w = threadIdx.x, e0 = c0(w), e1 = c0(w + 1);
1486	        int* my = wcnt + (int64_t)w * dec::kVocab;
1487	        for (int t = e0; t < e1; ++t) {
1488	            const int r = tok_ids[t];
1489	            if (r >= 0 && r < dec::kVocab) my[r]++;
1490	        }
1491	    }
1492	    __syncthreads();
1493	    // 3) exclusive prefix over r → row_start[V+1] (single thread; V tiny). totals[r]
1494	    //    = Σ_w wcnt[w][r]. row_start is exclusive over rows (CSR).
1495	    if (threadIdx.x == 0) {
1496	        int acc = 0;
1497	        for (int r = 0; r < dec::kVocab; ++r) {
1498	            row_start[r] = acc;
1499	            for (int w = 0; w < kW; ++w) acc += wcnt[(int64_t)w * dec::kVocab + r];
1500	        }
1501	        row_start[dec::kVocab] = acc;   // == #tokens with a valid row (≤ T)
1502	    }
1503	    __syncthreads();
1504	    // 4) per-(worker,row) base cursor: wcnt[w][r] ← row_start[r] + Σ_{w'<w} cnt[w'][r]
1505	    //    (ascending-worker prefix WITHIN a row → lower-t chunks land first). One
1506	    //    thread per row (V≤256 → fits blockDim) scans workers ascending.
1507	    if (threadIdx.x < dec::kVocab) {
1508	        const int r = threadIdx.x;
1509	        int base = row_start[r];
1510	        for (int w = 0; w < kW; ++w) {
1511	            int* slot = &wcnt[(int64_t)w * dec::kVocab + r];
1512	            const int c = *slot;
1513	            *slot = base;        // becomes the live append cursor for (w,r)
1514	            base += c;
1515	        }
1516	    }
1517	    __syncthreads();
1518	    // 5) scatter: each worker walks its chunk ascending t, appending t to perm at
1519	    //    its per-row cursor. Ascending t within the chunk + ascending-worker bases
1520	    //    ⇒ globally ascending t per row bucket.
1521	    if (threadIdx.x < kW) {
1522	        const int w = threadIdx.x, e0 = c0(w), e1 = c0(w + 1);
1523	        int* cur = wcnt + (int64_t)w * dec::kVocab;
1524	        for (int t = e0; t < e1; ++t) {
1525	            const int r = tok_ids[t];
1526	            if (r >= 0 && r < dec::kVocab) perm[cur[r]++] = t;
1527	        }
1528	    }
1529	    __syncthreads();
1530	}
