1532	// CONSUME: assemble tok + pos embedding grads from the prebuilt lists. Flat grid-
1533	// stride over V·d (tok) and S·d (pos) output elements → all CTAs + threads busy,
1534	// coalesced dh0 reads, fixed ascending-t accumulation per row (deterministic).
1535	__device__ __forceinline__ void dectc_embed_owner_scan(
1536	        const DecActs& acts, const int* __restrict__ row_start,
1537	        const int* __restrict__ perm, int T,
1538	        float* __restrict__ grad, int cta, int nCTA) {
1539	    const int tok_off = kDecOffsets[0];   // tok.weight [V,d]
1540	    const int pos_off = kDecOffsets[1];   // pos.weight [S,d]
1541	    const __nv_bfloat16* __restrict__ dh0 = acts.dh0;
1542	    const int stride = nCTA * blockDim.x;
1543	    const int base   = cta * blockDim.x + threadIdx.x;
1544	    // ── tok grad: element (r,j) over V·d, grid-strided. Walk ONLY row r's tokens
1545	    //    (perm[row_start[r] .. row_start[r+1])) ascending → coalesced dh0 column
1546	    //    read across the warp (consecutive j on one token row). ──
1547	    const int64_t Vd = (int64_t)dec::kVocab * dec::kD;
1548	    for (int64_t e = base; e < Vd; e += stride) {
1549	        const int r = (int)(e / dec::kD);
1550	        const int j = (int)(e - (int64_t)r * dec::kD);
1551	        const int s0 = row_start[r], s1 = row_start[r + 1];
1552	        float accv = 0.0f;
1553	        for (int i = s0; i < s1; ++i)
1554	            accv += __bfloat162float(dh0[(int64_t)perm[i] * dec::kD + j]);
1555	        grad[tok_off + e] = accv;
1556	    }
1557	    // ── pos grad: element (p,j) over S·d, grid-strided. Tokens with (t%S)==p are
1558	    //    t = p, p+S, …, p+(B-1)·S (T=B·S) — closed-form ascending walk, no list. ──
1559	    const int64_t Sd = (int64_t)dec::kSeq * dec::kD;
1560	    const int B = T / dec::kSeq;
1561	    for (int64_t e = base; e < Sd; e += stride) {
1562	        const int p = (int)(e / dec::kD);
1563	        const int j = (int)(e - (int64_t)p * dec::kD);
1564	        float accv = 0.0f;
1565	        int t = p;
1566	        for (int i = 0; i < B; ++i, t += dec::kSeq)
1567	            accv += __bfloat162float(dh0[(int64_t)t * dec::kD + j]);
1568	        grad[pos_off + e] = accv;
1569	    }
1570	}
1571	
1572	// ════════════════════════════════════════════════════════════════════════
1573	//  P2 — LN-vector grad reduce. The 10 γ/β grads were accumulated tile-locally
1574	//    into each CTA's lnvec partials [kNumLnVec × d]; sum across CTAs in
1575	//    ASCENDING CTA index (deterministic) into the 10 dec_layout slots of grad.
1576	//    `lnvec_base` is the start of the [nCTA × kLnVecElems] partial region.
1577	// ════════════════════════════════════════════════════════════════════════
1578	__device__ __forceinline__ void dectc_lnvec_reduce(
1579	        const float* __restrict__ lnvec_base, float* __restrict__ grad,
1580	        int nCTA, int cta) {
1581	    // Each CTA reduces a subset of the 10 LN tensors (round-robin by tensor).
1582	    for (int v = cta; v < kNumLnVec; v += nCTA) {
1583	        const int goff = kLnVecTensorIdx[v];
1584	        const int64_t gbase = kDecOffsets[goff];
1585	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1586	            float accv = 0.0f;
1587	            for (int c = 0; c < nCTA; ++c)
1588	                accv += lnvec_base[(int64_t)c * kLnVecElems + (int64_t)v * dec::kD + j];
1589	            grad[gbase + j] = accv;
1590	        }
1591	    }
1592	}
1593	
1594	}  // namespace dectc
1595	
1596	}}} // namespace sg::fused::sm90
